Ltac zcases c lo hi :=
  let b := eval vm_compute in (Z.ltb hi lo) in
  lazymatch b with
  | true => exfalso; lia
  | false => let lo' := eval vm_compute in (lo + 1)%Z in destruct (Z.eq_dec c lo) as [-> | ?]; [| zcases c lo' hi]
  end.

